function joinCompanion(){
 if(state.phase!=='setup'||state.team||recoveryBlocked)return false;
 try{const cfg=parseSessionCode($('#sessionInput').value),id=Number($('#teamSelect').value),mission=$('#vehicleSelect').value,all=createTeams(cfg);if(!all[id-1]||!validMission(mission))throw new Error('choice');
 state.sessionCode=cfg.code;state.teamCount=cfg.teamCount;state.teamId=id;state.team=all[id-1];state.team.mission=mission;state.lockedMission=null;state.vehicleConfirmed=false;state.round=0;state.lot=0;state.currentCard=null;phase('practice');renderAll();return true;
 }catch{seaNotify(t('errors.badCode'));return false}
}
function setStudentVehicle(mission){
 if(state.phase!=='planning'||state.lockedMission||!state.team||state.team.purchases.length||!validMission(mission))return false;
 if(state.team.mission===mission)return true;
 state.team.mission=mission;state.vehicleConfirmed=false;state.vehicleChangeNotice=true;saveState();renderAll();$('#planVehicleNotice').textContent=t('vehicle.changeNotice');return true;
}
function startStudentAuction(){
 if(state.phase!=='planning'||state.lockedMission||!state.team||!validMission(state.team.mission))return false;
 if(!state.vehicleConfirmed){seaNotify(t('vehicle.needConfirm'));return false}
 state.lockedMission=state.team.mission;state.team.lockedMission=state.team.mission;state.planBaseline=state.plan;
 phase('auction');renderAll();return true;
}
function validateStudentSave(x){
 const cfg=validateBase(x);must(hasOnlyKeys(x,['schema','phase','lang','vehicleConfirmed','lockedMission','sessionCode','teamCount','teamId','team','round','lot','currentCard','plan','planBaseline','risks','maxWtpCents','scratch','profitMode','profitInput','profitCents','practiceWon','vehicleChangeNotice']));
 must(x.vehicleChangeNotice===undefined||typeof x.vehicleChangeNotice==='boolean');must(x.team&&x.team.id===x.teamId&&x.teamId<=cfg.teamCount);
 const tm=cleanTeam(x.team);if(['auction','build','submit','debrief','closed'].includes(x.phase))must(x.lockedMission===tm.mission&&tm.lockedMission===tm.mission);else must(x.lockedMission===null&&tm.purchases.length===0);
 must(typeof x.vehicleConfirmed==='boolean'&&typeof x.practiceWon==='boolean');
 must(x.phase==='practice'||!x.practiceWon);
 for(const key of ['plan','risks'])must(typeof x[key]==='string'&&x[key].length<=1200);must(x.planBaseline===null||(typeof x.planBaseline==='string'&&x.planBaseline.length<=1200));
 must(validCents(x.maxWtpCents)&&validCents(x.profitCents)&&['AMOUNT','PERCENT'].includes(x.profitMode)&&typeof x.profitInput==='string'&&x.profitInput.length<=20);addCents(tm.cost,x.profitCents);
 must(x.scratch&&typeof x.scratch==='object'&&!Array.isArray(x.scratch)&&Object.keys(x.scratch).length<=70);
 for(const[key,v]of Object.entries(x.scratch))must(/^[1-7]-(10|[1-9])$/.test(key)&&hasOnlyKeys(v,['wtp','note'])&&Object.keys(v).length===2&&typeof v.wtp==='string'&&v.wtp.length<=20&&typeof v.note==='string'&&v.note.length<=600);
 if(x.currentCard){const c=cardAt(x.currentCard.id,x.round+1,x.lot+1);must(x.currentCard.instance===c.instance);x.currentCard=c}
 return {...x,team:tm,vehicleChangeNotice:x.vehicleChangeNotice===true};
}
function calculateDraftProfit(mode,input){
 const p=mode==='AMOUNT'?parseAmount(input):profitFromBps(state.team.cost,parsePercentBps(input));addCents(state.team.cost,p);return p;
}
function changeProfitMode(){
 if(state.phase!=='submit')return;const mode=$('#profitMode').value;
 if(mode===state.profitMode)return;
 if(mode==='AMOUNT'){state.profitMode=mode;state.profitInput=amountInput(state.profitCents)}
 else{if(state.team.cost===0&&state.profitCents!==0){$('#profitMode').value=state.profitMode;return}state.profitMode=mode;const bps=state.team.cost===0?0n:(BigInt(state.profitCents)*10000n+BigInt(Math.floor(state.team.cost/2)))/BigInt(state.team.cost);state.profitInput=(bps/100n).toString()+'.'+(bps%100n).toString().padStart(2,'0')}
 renderSubmit();
}

const STORE_KEY="SEA_STUDENT_V300";
let state={phase:"setup",schema:3,lang:"en",vehicleConfirmed:false,lockedMission:null,sessionCode:null,teamCount:0,teamId:null,team:null,round:0,lot:0,currentCard:null,plan:"",planBaseline:null,risks:"",maxWtpCents:85000000,scratch:{},profitMode:"AMOUNT",profitInput:"250000",profitCents:25000000,practiceWon:false};

function phase(p){
 const i=PHASES.indexOf(state.phase),j=PHASES.indexOf(p);if(j<0||!(i===j||j===i+1))return false;
 if(p==='auction'&&!state.lockedMission)return false;
 const moved=state.phase!==p;state.phase=p;$$('.section').forEach(x=>x.classList.toggle('active',x.id===p));$('#phaseBadge').textContent=t('phase.'+p);if(moved){window.scrollTo(0,0);const h=document.querySelector('#'+p+' h2');if(h){h.tabIndex=-1;h.focus({preventScroll:true})}}saveState();return true;
}

function saveState(){if(recoveryBlocked)return false;if(!state.sessionCode)return true;try{state.lang=lang;sessionStorage.setItem(STORE_KEY,JSON.stringify(state));return true}catch{storageFailed=true;storageNotice('common.refresh');return false}}

function restoreState(){
 let raw;try{raw=sessionStorage.getItem(STORE_KEY)}catch{storageFailed=true;return false}if(!raw)return false;
 try{must(raw.length<=MAX_BACKUP_CHARS);const x=validateStudentSave(JSON.parse(raw));state=x;lang=x.lang;return true}catch{recoveryBlocked=true;storageNotice('common.badRecovery');return false}
}
let pendingBackupImport=null,backupImportGeneration=0,backupStatusKey=null;
function backupStatus(key){backupStatusKey=key;const el=$('#backupStatus');if(el){el.textContent=t(key);el.classList.remove('hidden')}}
function saveBackupDownload(raw,suffix=''){
 const blob=new Blob([raw],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');
 a.href=url;a.download=`sea-student-${suffix? suffix+'-':''}${new Date().toISOString().slice(0,10)}.json`;a.hidden=true;document.body.appendChild(a);
 try{a.click()}finally{a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
}
function exportBackup(){
 try{
  if(recoveryBlocked){const raw=sessionStorage.getItem(STORE_KEY);if(!raw)return backupStatus('backup.invalid');saveBackupDownload(JSON.stringify({format:'SEA-GAME-RECOVERY-RESCUE',version:1,role:'STUDENT',raw}),'recovery');backupStatus('backup.rawExported');return}
  if(!state.sessionCode)return backupStatus('backup.noSession');
  saveBackupDownload(makeBackup('STUDENT',state));backupStatus('backup.exported');
 }catch{backupStatus('backup.failed')}
}
function commitBackupImport(token){
 const pending=pendingBackupImport;if(!pending||pending.token!==token)return false;
 if(!seaConfirmGate('backup-import-'+token,t('backup.confirmStudent'),()=>commitBackupImport(token)))return false;
 if(JSON.stringify(state)!==pending.before){pendingBackupImport=null;backupStatus('backup.changed');return false}
 if(state.sessionCode){
  const previous=makeBackup('STUDENT',state);
  try{sessionStorage.setItem(STORE_KEY+'_PRE_IMPORT',previous)}catch{}
  try{saveBackupDownload(previous,'pre-import')}catch{pendingBackupImport=null;backupStatus('backup.failed');return false}
 }else if(recoveryBlocked){
  try{const raw=sessionStorage.getItem(STORE_KEY);if(raw){const rescue=JSON.stringify({format:'SEA-GAME-RECOVERY-RESCUE',version:1,role:'STUDENT',raw});try{sessionStorage.setItem(STORE_KEY+'_PRE_IMPORT_RAW',rescue)}catch{}saveBackupDownload(rescue,'recovery-pre-import')}}catch{pendingBackupImport=null;backupStatus('backup.failed');return false}
 }
 state=pending.candidate;pendingBackupImport=null;lang=state.lang;recoveryBlocked=false;storageFailed=false;
 const saved=saveState();$('#sessionInput').value=state.sessionCode;populateTeamSelect(state.sessionCode);$('#teamSelect').value=String(state.teamId);
 phase(state.phase);renderAll();backupStatus(saved?'backup.imported':'backup.storageFailed');return true;
}
async function readBackupFile(file){
 const token=++backupImportGeneration;pendingBackupImport=null;if(!file)return;
 if(file.size>MAX_BACKUP_BYTES)return backupStatus('backup.tooLarge');
 const original=state,before=JSON.stringify(state);
 try{
  const raw=await file.text();if(token!==backupImportGeneration)return;
  if(state!==original||JSON.stringify(state)!==before)return backupStatus('backup.changed');
  const candidate=parseBackup(raw,'STUDENT',validateStudentSave,MAX_BACKUP_CHARS);
  pendingBackupImport={token,candidate,before};
  commitBackupImport(token);
 }catch{if(token===backupImportGeneration)backupStatus('backup.invalid')}
}
function restorePreviousBackup(){
 const token=++backupImportGeneration;pendingBackupImport=null;
 try{const raw=sessionStorage.getItem(STORE_KEY+'_PRE_IMPORT');if(!raw){backupStatus('backup.noPrevious');return false}const candidate=parseBackup(raw,'STUDENT',validateStudentSave,MAX_BACKUP_CHARS);pendingBackupImport={token,candidate,before:JSON.stringify(state)};return commitBackupImport(token)}
 catch{backupStatus('backup.invalid');return false}
}
function resetClosedSession(before){
 if(state.phase!=='closed'||JSON.stringify(state)!==before){backupStatus('backup.changed');return false}
 let previous;try{previous=makeBackup('STUDENT',state)}catch{backupStatus('backup.failed');return false}
 let storageIssue=false;try{sessionStorage.setItem(STORE_KEY+'_PRE_IMPORT',previous)}catch{storageIssue=true}
 try{saveBackupDownload(previous,'pre-reset')}catch{backupStatus('backup.failed');return false}
 try{sessionStorage.removeItem(STORE_KEY)}catch{storageIssue=true}
 const language=state.lang;state={phase:'setup',schema:3,lang:language,vehicleConfirmed:false,lockedMission:null,sessionCode:null,teamCount:0,teamId:null,team:null,round:0,lot:0,currentCard:null,plan:'',planBaseline:null,risks:'',maxWtpCents:85000000,scratch:{},profitMode:'AMOUNT',profitInput:'250000',profitCents:25000000,practiceWon:false};
 lang=language;recoveryBlocked=false;storageFailed=storageIssue;$('#sessionInput').value='';$('#teamSelect').innerHTML='<option value="">-</option>';$('#joinStatus').className='notice info';$('#joinStatus').textContent=t('setup.waiting');phase('setup');renderAll();backupStatus('backup.exported');return true;
}
function startNewSession(){
 if(state.phase!=='closed'||!state.sessionCode)return false;
 const before=JSON.stringify(state);
 if(!seaConfirmGate('new-session',t('closed.newConfirm'),()=>resetClosedSession(before)))return false;
 return resetClosedSession(before);
}
function renderBackupControls(){
 $('#exportBackupBtn').disabled=!state.sessionCode&&!recoveryBlocked;
 try{$('#restorePreviousBtn').disabled=!sessionStorage.getItem(STORE_KEY+'_PRE_IMPORT')}catch{$('#restorePreviousBtn').disabled=true}
 if(backupStatusKey)backupStatus(backupStatusKey)
}
function scratchKey(){return `${state.round+1}-${state.lot+1}`}
function scratch(){return state.scratch[scratchKey()]||(state.scratch[scratchKey()]={wtp:"",note:""})}
function bindScratchInputs(){
 const key=scratchKey(),session=state.sessionCode,team=state.team,wtp=$('#wtp'),decision=$('#decision');
 const current=element=>state.phase==='auction'&&team&&state.team===team&&state.sessionCode===session&&scratchKey()===key&&element.isConnected&&Number.isInteger(state.round)&&state.round>=0&&state.round<7&&Number.isInteger(state.lot)&&state.lot>=0&&state.lot<10;
 wtp.onchange=e=>{if(!current(wtp))return;try{const value=String(parseWholeDollars(e.target.value)/100);scratch().wtp=value;e.target.value=value;saveState()}catch{seaNotify(t('errors.badMoney'));e.target.value=state.scratch[key]?.wtp||''}};
 decision.oninput=e=>{if(!current(decision))return;if(e.target.value.length>600){e.target.value=state.scratch[key]?.note||'';return}scratch().note=e.target.value;saveState()};
}

function populateTeamSelect(code){const cfg=parseSessionCode(code),prev=$('#teamSelect').value;$('#teamSelect').innerHTML=`<option value="">${t('setup.team')}</option>`+Array.from({length:cfg.teamCount},(_,i)=>`<option value="${i+1}">${t('common.team',{n:i+1})}</option>`).join('');if(Number(prev)>0&&Number(prev)<=cfg.teamCount)$('#teamSelect').value=prev;return cfg}
function renderRequirements(){const r=req(state.team);$("#reqTable").innerHTML=`<tr><th>${t("planning.requirements")}</th><th>${t("common.minimum")}</th></tr>`+Object.entries(r).map(([k,v])=>`<tr><td>${esc(LABELS[k][lang][0])}</td><td>${v} ${esc(LABELS[k][lang][1])}</td></tr>`).join("")}

function renderPractice(){const artEl=$('#practiceArt');if(artEl&&!artEl.firstChild)artEl.innerHTML=art({id:'TRAIN-CAP',title:{en:'Training capacity',fr:'Capacité de formation'}});$('#toPlanning').disabled=!state.practiceWon;$('#practiceStatus').textContent=state.practiceWon?t('practice.statusWon',{amount:money(35000000)}):t('practice.statusReady');saveState()}

function renderPlanning(){
 $('#planningTitle').textContent=`${t('common.team',{n:state.team.id})} - ${MISSIONS[state.team.mission][lang]}`;
 $('#planVehicle').innerHTML=vehicleOptions(state.team.mission);$('#planVehicle').disabled=!!state.lockedMission;$('#vehicleConfirmed').checked=state.vehicleConfirmed;
 renderVehiclePreview('planVehiclePreview',state.team.mission);
 $('#planVehicleNotice').textContent=state.vehicleChangeNotice?t('vehicle.changeNotice'):'';$('#toAuction').disabled=!state.vehicleConfirmed;$('#plan').value=state.plan;$('#risks').value=state.risks;$('#maxWtp').value=amountInput(state.maxWtpCents);renderRequirements();
}
function currentExpectedSlot(){return SLOT_ORDER[state.lot]}

function loadCurrentCard(){if(state.phase!=='auction')return;const raw=$('#cardInput').value.trim().toUpperCase(),c=CARD_INDEX.get(raw);if(!c)return seaNotify(t('errors.badCard'));const slot=currentExpectedSlot();if(c.cat!==slot)return seaNotify(t('errors.wrongSlot',{slot:categoryName(slot)}));state.currentCard=cardAt(c.id,state.round+1,state.lot+1);saveState();renderAuction()}
function renderCard(){const c=state.currentCard;if(!c){$("#cardCat").textContent="-";$("#cardId").textContent="-";$("#cardTitle").textContent=t("common.hidden");$("#cardEffects").innerHTML="";$("#cardArt").innerHTML=`<div style="height:100%;display:grid;place-items:center">${t("common.hidden")}</div>`;$("#startPrice").textContent="";$("#wonPrice").value="";$("#wonPrice").dataset.cardId="";return}$("#cardCat").textContent=categoryName(c.cat);$("#cardId").textContent=c.id;$("#cardTitle").textContent=c.title[lang];$("#cardEffects").innerHTML=effectsHtml(c);$("#cardArt").innerHTML=art(c);$("#startPrice").textContent=t("common.starting",{amount:money(c.start)});const paid=$("#wonPrice");if(paid.dataset.cardId!==c.id){paid.value=amountInput(c.start);paid.dataset.cardId=c.id}}

function renderGaps(){
 const c=state.currentCard,parts=[];for(const[k,min]of Object.entries(req(state.team))){const now=state.team.totals[k],after=c?now+(c.e[k]||0):now;
 if(now<min||after<min)parts.push(`${LABELS[k][lang][0]} ${now}/${min}${c?` → ${after}/${min}`:''}`)}
 $('#gapNotice').textContent=parts.length?parts.join(' · '):t('auction.noGaps');
}
function renderSnapshot(){const tm=state.team;$("#snapshotMetrics").innerHTML=`<div class="metric"><div class="label">${t("common.cost")}</div><div class="value">${money(tm.cost)}</div></div><div class="metric"><div class="label">${t("common.score")}</div><div class="value">${score(tm)}</div></div>`;$("#auctionInventory").innerHTML=tm.purchases.length?tm.purchases.map(p=>`<div class="purchase-row"><span>R${p.round}·L${p.lot}</span><span>${esc(p.id)} - ${esc(p.title[lang])}</span><strong>${money(p.paid)}</strong></div>`).join(""):`<div class="muted">${t("auction.noPurchases")}</div>`}
function renderAuction(){$("#roundSelect").value=String(state.round+1);$("#lotSelect").value=String(state.lot+1);const s=state.scratch[scratchKey()]||{wtp:"",note:""};$("#wtp").value=s.wtp;$("#decision").value=s.note;bindScratchInputs();renderCard();renderGaps();renderSnapshot();saveState()}

function setPosition(){if(state.phase!=='auction')return;const round=Number($('#roundSelect').value),lot=Number($('#lotSelect').value);if(!Number.isInteger(round)||round<1||round>7||!Number.isInteger(lot)||lot<1||lot>10)return;state.round=round-1;state.lot=lot-1;state.currentCard=null;$('#cardInput').value='';$('#wonPrice').value='';$('#wonPrice').dataset.cardId='';renderAuction()}

function recordWin(){
 if(state.phase!=='auction'||!state.lockedMission)return false;
 if(!state.currentCard){seaNotify(t('errors.loadFirst'));return false}
 try{acquire(state.team,state.currentCard,parseWholeDollars($('#wonPrice').value));state.currentCard=null;saveState();advancePosition();return true}
 catch(e){seaNotify(t(e.message==='duplicate'?'errors.duplicate':e.message==='limit'?'errors.purchaseLimit':'errors.moneyRange'));return false}
}

function advancePosition(){if(state.phase!=='auction')return false;if(state.lot<9)state.lot++;else if(state.round<6){state.round++;state.lot=0}else{state.currentCard=null;phase('build');renderAll();return true}state.currentCard=null;$('#cardInput').value='';$('#wonPrice').value='';$('#wonPrice').dataset.cardId='';renderAuction();return true}

function finishStudentAuction(){
 if(state.phase!=='auction')return false;
 const original=state,team=state.team,before=JSON.stringify(state);
 const apply=()=>{if(state!==original||state.team!==team||state.phase!=='auction'||JSON.stringify(state)!==before){seaNotify(t('errors.changed'));return false}state.currentCard=null;if(!phase('build'))return false;renderAll();return true};
 if(!seaConfirmGate('finish-auction',t('auction.finishConfirm'),apply))return false;
 return apply();
}

function removePurchase(team,index){must(Number.isInteger(index)&&index>=0&&index<team.purchases.length);const item=team.purchases[index],totals={...team.totals};for(const[k,v]of Object.entries(item.e))totals[k]-=v;team.purchases=team.purchases.filter((_,i)=>i!==index);team.purchasesByRound=[...team.purchasesByRound];team.purchasesByRound[item.round-1]--;team.cost-=item.paid;team.totals=totals}
function removePurchaseByInstance(team,instance){const matches=team.purchases.reduce((count,p)=>count+(p.instance===instance?1:0),0);if(matches!==1)return false;const index=team.purchases.findIndex(p=>p.instance===instance);removePurchase(team,index);return true}
function requestPurchaseRemoval(instance,intent){
 if(state.phase!=='build')return false;
 if(!intent)intent={team:state.team,session:state.sessionCode,purchase:state.team?.purchases.find(p=>p.instance===instance)};
 if(!state.team||intent.team!==state.team||intent.session!==state.sessionCode||!intent.purchase||!state.team.purchases.includes(intent.purchase)){seaNotify(t('errors.stale'));return false}
 if(!seaConfirmGate('remove-purchase-'+instance,t('common.correctOnly'),()=>requestPurchaseRemoval(instance,intent)))return false;
 if(!removePurchaseByInstance(state.team,instance)){seaNotify(t('errors.stale'));return false}
 saveState();renderBuild();return true;
}
function renderReconcileInventory(){
 const team=state.team,session=state.sessionCode;
 $('#reconcileInventory').innerHTML=state.team.purchases.length?state.team.purchases.map(p=>`<div class="purchase-row"><span>R${p.round}·L${p.lot}</span><span>${esc(p.id)} - ${esc(p.title[lang])}</span><span><strong>${money(p.paid)}</strong> <button class="btn" data-remove-purchase="${esc(p.instance)}">${t('common.remove')}</button></span></div>`).join(''):`<div class="muted">${t('auction.noPurchases')}</div>`;
 $$('[data-remove-purchase]').forEach(b=>{const instance=b.dataset.removePurchase,intent={team,session,purchase:team.purchases.find(p=>p.instance===instance)};b.onclick=()=>{if(!b.isConnected)return false;return requestPurchaseRemoval(instance,intent)}});
}

function addMissingPurchase(){
 if(state.phase!=='build')return false;
 try{const c=cardAt($('#addCard').value.trim().toUpperCase(),Number($('#addRound').value),Number($('#addLot').value)),paid=parseWholeDollars($('#addPrice').value);acquire(state.team,c,paid);$('#addCard').value='';$('#addPrice').value='';saveState();renderBuild();return true}
 catch(e){seaNotify(t(e.message==='duplicate'?'errors.duplicate':e.message==='limit'?'errors.purchaseLimit':'errors.moneyRange'));return false}
}
function renderBuild(){renderReconcileInventory();$("#capMetrics").innerHTML=Object.entries(state.team.totals).map(([k,v])=>`<div class="metric"><div class="label">${esc(LABELS[k][lang][0])}</div><div class="value">${v}</div></div>`).join("");$("#complianceTable").innerHTML=`<tr><th>${t("planning.requirements")}</th><th>${t("common.total")}</th><th>${t("common.minimum")}</th><th>${t("common.status")}</th></tr>`+Object.entries(req(state.team)).map(([k,min])=>`<tr><td>${esc(LABELS[k][lang][0])}</td><td>${state.team.totals[k]}</td><td>${min}</td><td class="${state.team.totals[k]>=min?"pass":"fail"}">${state.team.totals[k]>=min?t("common.pass"):t("common.shortfall")}</td></tr>`).join("");$("#overall").className="notice "+(compliant(state.team)?"good":"bad");$("#overall").textContent=compliant(state.team)?t("build.allPass"):t("build.hasShortfalls");saveState()}

function calculateProfit(){try{state.profitCents=calculateDraftProfit(state.profitMode,state.profitInput);return true}catch{return false}}

function renderSubmit(){
 $('#profitMode').value=state.profitMode;$('#profitInput').value=state.profitInput;$('#profitLabel').textContent=t(state.profitMode==='AMOUNT'?'submit.valueAmount':'submit.valuePercent');
 const ok=calculateProfit(),sc=score(state.team),bid=ok?addCents(state.team.cost,state.profitCents):null;
 $('#submitMetrics').innerHTML=`<div class="metric"><div class="label">${t('common.cost')}</div><div class="value">${money(state.team.cost)}</div></div><div class="metric"><div class="label">${t('common.profit')}</div><div class="value">${ok?money(state.profitCents,2):'-'}</div></div><div class="metric"><div class="label">${t('common.bid')}</div><div class="value">${ok?money(bid,2):'-'}</div></div><div class="metric"><div class="label">${t('common.cpp')}</div><div class="value">${ok?ratioDisplay(bid,sc):'-'}</div></div>`;
 $('#profitInput').setAttribute('aria-invalid',String(!ok));$('#toDebrief').disabled=!ok;
 $('#eligibility').className='notice '+(ok&&compliant(state.team)&&sc>0?'good':'bad');$('#eligibility').textContent=!ok?t('errors.moneyRange'):compliant(state.team)&&sc>0?t('submit.localEligible'):t('submit.localIneligible');saveState();
}
function renderDebrief(){const sc=score(state.team),bid=addCents(state.team.cost,state.profitCents),procs=state.team.purchases.filter(p=>p.cat==="SE_PROCESS");$("#debriefCard").innerHTML=`<h3>${t("common.team",{n:state.team.id})} - ${esc(MISSIONS[state.team.mission][lang])}</h3><p>${compliant(state.team)?t("common.compliant"):t("common.noncompliant")} · ${t("common.score")} ${sc} · ${t("common.cost")} ${money(state.team.cost)} · ${t("common.profit")} ${money(state.profitCents)} · ${t("common.bid")} ${money(bid)} · ${t("common.cpp")} ${ratioDisplay(bid,sc)}</p><p><strong>${t("debrief.originalPlan")}:</strong> ${esc((state.planBaseline??state.plan)||"-")}</p><p><strong>${t("debrief.risks")}:</strong> ${esc(state.risks||"-")}</p><p><strong>${t("debrief.outcome")}:</strong> ${state.team.purchases.length} ${t("common.purchases")}; ${compliant(state.team)?t("common.compliant"):t("common.noncompliant")}. ${procs.length?`${t("debrief.process")}: ${esc(procs[0].title[lang])}`:t("debrief.noProcess")}</p>`;saveState()}

function renderAll(){
 state.lang=lang;applyI18n();renderBackupControls();$('#phaseBadge').textContent=t('phase.'+state.phase);$('#sessionBadge').textContent=state.sessionCode||'-';
 $('#vehicleBadge').textContent=state.team?`${t('common.team',{n:state.team.id})} · ${MISSIONS[state.team.mission][lang]}${state.lockedMission?' · '+t('vehicle.locked'):''}`:t('vehicle.choose');
 if(state.phase==='setup'){const selected=$('#vehicleSelect').value;$('#vehicleSelect').innerHTML=vehicleOptions(selected);renderVehiclePreview('setupVehiclePreview',selected);if($('#sessionInput').value){try{populateTeamSelect($('#sessionInput').value);$('#joinStatus').textContent=t('setup.valid')}catch{$('#joinStatus').textContent=t('setup.invalid')}}}
 if(state.phase==='practice')renderPractice();if(state.phase==='planning')renderPlanning();if(state.phase==='auction')renderAuction();if(state.phase==='build')renderBuild();if(state.phase==='submit')renderSubmit();if(state.phase==='debrief')renderDebrief();if(state.phase==='closed'){renderDebrief();$('#closedSummary').innerHTML=$('#debriefCard').innerHTML}
 if(recoveryBlocked)storageNotice('common.badRecovery');else if(storageFailed)storageNotice('common.refresh');
}
$("#teamSelect").innerHTML=`<option value="">-</option>`;
$("#vehicleSelect").innerHTML=vehicleOptions(null);
$("#roundSelect").innerHTML=Array.from({length:7},(_,i)=>`<option value="${i+1}">${i+1}</option>`).join("");
$("#lotSelect").innerHTML=Array.from({length:10},(_,i)=>`<option value="${i+1}">${i+1}</option>`).join("");
$("#addRound").innerHTML=$("#roundSelect").innerHTML;$("#addLot").innerHTML=$("#lotSelect").innerHTML;
$("#sessionInput").oninput=()=>{try{populateTeamSelect($("#sessionInput").value);$("#joinStatus").className="notice good";$("#joinStatus").textContent=t("setup.valid")}catch{$("#teamSelect").innerHTML=`<option value="">-</option>`;$("#joinStatus").className="notice bad";$("#joinStatus").textContent=t("setup.invalid")}};
$("#joinBtn").onclick=joinCompanion;
$("#practiceRecord").onclick=()=>{if(state.phase!=="practice"||state.practiceWon)return;state.practiceWon=true;renderPractice()};
$("#practiceReset").onclick=()=>{if(state.phase!=="practice"||!state.practiceWon)return;state.practiceWon=false;renderPractice()};
$("#toPlanning").onclick=()=>{if(state.phase!=="practice"||!state.practiceWon)return;state.practiceWon=false;phase("planning");renderAll()};
$("#plan").oninput=e=>{if(state.phase!=="planning"||state.lockedMission)return;if(e.target.value.length>1200){e.target.value=state.plan;return}state.plan=e.target.value;saveState()};
$("#risks").oninput=e=>{if(state.phase!=="planning"||state.lockedMission)return;if(e.target.value.length>1200){e.target.value=state.risks;return}state.risks=e.target.value;saveState()};
$("#maxWtp").onchange=e=>{if(state.phase!=="planning"||state.lockedMission)return;try{state.maxWtpCents=parseWholeDollars(e.target.value);saveState()}catch{seaNotify(t("errors.badMoney"));e.target.value=state.maxWtpCents/100}};
$("#toAuction").onclick=startStudentAuction;
$("#roundSelect").onchange=setPosition;$("#lotSelect").onchange=setPosition;
$("#loadCardBtn").onclick=loadCurrentCard;
bindScratchInputs();
$("#recordWinBtn").onclick=recordWin;
$("#advanceLocalBtn").onclick=advancePosition;
$("#addPurchaseBtn").onclick=addMissingPurchase;
$("#toSubmit").onclick=()=>{if(state.phase!=="build")return;phase("submit");renderAll()};
$("#profitMode").onchange=changeProfitMode;
$("#profitInput").oninput=()=>{if(state.phase!=="submit")return;const input=$("#profitInput");if(input.value.length>20){input.value=state.profitInput;return}state.profitInput=input.value;renderSubmit()};
$("#toDebrief").onclick=()=>{if(state.phase!=="submit")return;if(!calculateProfit())return seaNotify(t("errors.badMoney"));phase("debrief");renderAll()};
$("#vehicleSelect").onchange=()=>renderVehiclePreview("setupVehiclePreview",$("#vehicleSelect").value);
$("#planVehicle").onchange=e=>setStudentVehicle(e.target.value);
$("#vehicleConfirmed").onchange=e=>{if(state.phase!=="planning"||state.lockedMission)return;state.vehicleConfirmed=e.target.checked;saveState();$("#toAuction").disabled=!state.vehicleConfirmed};
$("#finishAuctionBtn").onclick=finishStudentAuction;
$("#toClosed").onclick=()=>{if(state.phase!=="debrief")return;phase("closed");renderAll()};


$('#exportBackupBtn').onclick=exportBackup;
$('#importBackupBtn').onclick=()=>$('#backupFile').click();
$('#restorePreviousBtn').onclick=restorePreviousBackup;
$('#startNewSessionBtn').onclick=startNewSession;
$('#backupFile').onchange=e=>{const file=e.target.files?.[0];e.target.value='';readBackupFile(file)};
$("#langBtn").onclick=()=>setLang(lang==="en"?"fr":"en");
bindArtworkEvents();
if(restoreState()){$("#sessionInput").value=state.sessionCode;populateTeamSelect(state.sessionCode);$("#teamSelect").value=String(state.teamId);$("#joinStatus").className="notice good";$("#joinStatus").textContent=t("setup.recovered");phase(state.phase)}else{$("#joinStatus").textContent=safeSessionStorage()?t("setup.waiting"):t("setup.noStorage");phase("setup")}
renderAll();
